components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 20px;
  font-size: 14px;
  font-weight: 500;
  font-family: system-ui, -apple-system, sans-serif;
  color: #FFFFFF;
  background: #4A7A49;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 1px 2px rgba(45,36,32,0.06);
}
.ds-btn-primary:hover {
  background: #3D613C;
}
.ds-btn-primary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #C8956C;
  box-shadow: 0 0 0 2px #C8956C, 0 0 0 4px #FFFFFF;
}
.ds-btn-primary:active {
  background: #355335;
}
.ds-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-btn-accent {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  padding: 0 28px;
  font-size: 16px;
  font-weight: 600;
  font-family: system-ui, -apple-system, sans-serif;
  color: #FFFFFF;
  background: #C8956C;
  border: 1px solid transparent;
  border-radius: 9999px;
  cursor: pointer;
  transition: background-color 0.15s ease, opacity 0.15s ease;
}
.ds-btn-accent:hover {
  background: #B07D54;
}
.ds-btn-accent:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #C8956C, 0 0 0 4px #FFFFFF;
}
.ds-btn-accent:active {
  background: #9C6F48;
}
.ds-btn-accent:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 20px;
  font-size: 14px;
  font-weight: 500;
  font-family: system-ui, -apple-system, sans-serif;
  color: #2D2420;
  background: transparent;
  border: 1px solid #E8E0D8;
  border-radius: 10px;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.ds-btn-outline:hover {
  background: #F5F0EB;
  border-color: #7A6E68;
}
.ds-btn-outline:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #C8956C, 0 0 0 4px #FFFFFF;
}
.ds-btn-outline:active {
  background: #E8E0D8;
}
.ds-btn-outline:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  color: #6B5E58;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.ds-btn-ghost:hover {
  background: #F5F0EB;
  color: #2D2420;
}
.ds-btn-ghost:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #C8956C;
}
.ds-btn-ghost:active {
  background: #E8E0D8;
}
.ds-btn-ghost:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-card-product {
  background: #FDF8F4;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}
.ds-card-product:hover {
  box-shadow: 0 8px 30px rgba(45,36,32,0.10);
  transform: translateY(-4px);
}
.ds-card-product-image {
  position: relative;
  aspect-ratio: 1;
  background: #F5F0EB;
  overflow: hidden;
}
.ds-card-product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.ds-card-product:hover .ds-card-product-image img {
  transform: scale(1.05);
}
.ds-card-product-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 600;
  font-family: system-ui, -apple-system, sans-serif;
  color: #4A7A49;
  background: #FFFFFF;
  border-radius: 9999px;
  box-shadow: 0 1px 2px rgba(45,36,32,0.06);
}
.ds-card-product-body {
  padding: 20px;
}
.ds-card-product-category {
  font-size: 12px;
  font-family: system-ui, -apple-system, sans-serif;
  color: #7A6E68;
}
.ds-card-product-name {
  margin: 4px 0;
  font-size: 16px;
  font-weight: 600;
  font-family: system-ui, -apple-system, sans-serif;
  color: #2D2420;
}
.ds-card-product-desc {
  margin: 0 0 12px 0;
  font-size: 12px;
  line-height: 1.5;
  font-family: system-ui, -apple-system, sans-serif;
  color: #7A6E68;
}
.ds-card-product-price {
  font-size: 18px;
  font-weight: 700;
  font-family: system-ui, -apple-system, sans-serif;
  color: #2D2420;
}

.ds-input {
  width: 100%;
  height: 44px;
  padding: 0 16px;
  font-size: 15px;
  font-family: system-ui, -apple-system, sans-serif;
  color: #2D2420;
  background: #FFFFFF;
  border: 1px solid #E8E0D8;
  border-radius: 10px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}
.ds-input::placeholder {
  color: #7A6E68;
}
.ds-input:hover {
  border-color: #C8956C;
}
.ds-input:focus {
  outline: none;
  border-color: #4A7A49;
  box-shadow: 0 0 0 2px rgba(200,149,108,0.5);
}
.ds-input.ds-input-error {
  border-color: #D4726A;
  background: #FDF0EE;
}
.ds-input.ds-input-error:focus {
  box-shadow: 0 0 0 2px rgba(212,114,106,0.5);
}
.ds-input:disabled {
  opacity: 0.5;
  background: #F5F0EB;
  cursor: not-allowed;
}

.ds-chip-tag {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 600;
  font-family: system-ui, -apple-system, sans-serif;
  color: #4A7A49;
  background: #FFFFFF;
  border-radius: 9999px;
  box-shadow: 0 1px 2px rgba(45,36,32,0.06);
}

.ds-nav-header {
  position: sticky;
  top: 0;
  z-index: 40;
  height: 72px;
  background: #FFFFFF;
  border-bottom: 1px solid #E8E0D8;
}
.ds-nav-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 16px;
}
.ds-nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.ds-nav-logo-text {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: #2D2420;
}
.ds-nav-links {
  display: none;
  align-items: center;
  gap: 4px;
}
@media (min-width: 1024px) {
  .ds-nav-links { display: flex; }
}
.ds-nav-link {
  padding: 8px 12px;
  font-size: 14px;
  font-weight: 500;
  font-family: system-ui, -apple-system, sans-serif;
  color: #6B5E58;
  text-decoration: none;
  border-radius: 6px;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.ds-nav-link:hover {
  background: #F5F0EB;
  color: #2D2420;
}
.ds-nav-link.active {
  color: #C8956C;
  background: rgba(200,149,108,0.1);
}
